import {recoveryCopy} from './recovery-demo-copy.js?v=5.12.0';
import {request} from './cloud.js?v=5.11.0';
import {CLOUD} from './cloud-config.js?v=5.6.0';
import {ownerCredential,legacyOwnerCredential,readJson,clearOwnerCache,parseShopLink,shopId} from './owner-access.js?v=5.11.0';
import {ownerAuthCopy} from './owner-auth-copy.js?v=5.11.0';
import {createOwnerSample} from './owner-sample.js?v=5.6.0';
import {esc,languageOptions,icon} from './core.js?v=5.6.0';
import {brandMark,brandLogo} from './brand.js?v=5.6.0';
export function createOwnerAuth({root,getLang,onReady,onLocked,onSuspend}){
 const initial=new URLSearchParams(location.search),known=initial.has('store')?initial.get('store'):readJson(localStorage,'modu-current-owner')||readJson(localStorage,'one-shop-linked-demo')?.storeId;
 const auth={generation:0,ready:false,storeId:shopId(known)?known:null,mode:known?'login':'choose',credential:null,legacy:null,name:'',error:'',pending:false,timer:null,
  t(key){return ownerAuthCopy(getLang())[key]||ownerAuthCopy(getLang()).cloudError;},
  async boot(){const generation=++this.generation;this.pending=true;this.render();try{if(this.storeId){this.credential=ownerCredential(localStorage,this.storeId);this.legacy=legacyOwnerCredential(localStorage,this.storeId);const baseline=localStorage.getItem('modu-owner-session:'+this.storeId);const info=await request(this.storeId+'/owner-auth','GET',null,this.credential?.token||this.legacy?.token);if(generation!==this.generation)return;if(localStorage.getItem('modu-owner-session:'+this.storeId)!==baseline)return this.invalidate();this.name=info.name||'';if(info.mode==='session'&&this.credential){this.pending=false;await this.enter(this.credential);return;}this.mode=info.mode==='setup'?'setup':'login';this.credential=null;}}catch(e){if(generation!==this.generation)return;this.error=e.message;}this.pending=false;this.render();},
  remember(c){localStorage.setItem('modu-owner-session:'+c.storeId,JSON.stringify(c));if(initial.get('demo')!=='shared')localStorage.setItem('modu-current-owner',JSON.stringify(c.storeId));localStorage.removeItem('modu-owner:'+c.storeId);const linked=readJson(localStorage,'one-shop-linked-demo');if(linked?.storeId===c.storeId)localStorage.removeItem('one-shop-linked-demo');},
  async enter(c){this.remember(c);this.storeId=c.storeId;this.credential=c;this.legacy=null;this.ready=true;this.error='';clearTimeout(this.timer);this.timer=setTimeout(()=>this.lock('expired'),Math.max(0,Date.parse(c.expiresAt)-Date.now()));const url=new URL(location.href);url.searchParams.set('store',c.storeId);url.searchParams.delete('preview');url.searchParams.delete('live');history.replaceState(null,'',url);await onReady(c);},
  lock(message='expired'){this.generation++;const previous=this.credential?.token;onLocked();this.ready=false;this.pending=false;this.credential=null;this.legacy=null;clearTimeout(this.timer);if(this.storeId)clearOwnerCache(localStorage,this.storeId,previous);this.mode='login';this.error=message;this.render();},
  invalidate(){this.generation++;onLocked();this.ready=false;this.pending=false;this.credential=null;clearTimeout(this.timer);this.mode='login';this.error='expired';this.render();},
  async logout(){if(this.pending||!this.credential)return;const generation=++this.generation,credential=this.credential,storeId=this.storeId;this.pending=true;onSuspend();const stale=()=>generation!==this.generation||ownerCredential(localStorage,storeId)?.token!==credential.token;try{await request(storeId+'/owner-auth/logout','POST',{},credential.token);if(stale()){if(generation===this.generation)this.invalidate();return;}this.lock('entrySaved');}catch(e){if(stale()){if(generation===this.generation)this.invalidate();return;}this.pending=false;await onReady(credential);this.feedback(e.message);}},
  managerLink(){const u=new URL('owner.html',CLOUD.guestBase);u.search=new URLSearchParams({store:this.storeId,lang:getLang(),v:'5.12.0'});return u.href;},
  feedback(key){this.error=key;const p=root.querySelector('[data-auth-feedback]');if(p){p.textContent=this.t(key);p.focus();}else this.render();},
  field(name,autocomplete='new-password'){return `<label for="auth-${name}">${esc(this.t(name==='password'?'password':name))}</label><div class="auth-password"><input id="auth-${name}" name="${name}" type="password" autocomplete="${autocomplete}" minlength="12" maxlength="128" required aria-describedby="auth-hint auth-feedback"><button type="button" data-auth="show" data-for="auth-${name}" aria-controls="auth-${name}" aria-pressed="false">${esc(this.t('show'))}</button></div>`;},
  passwordForm(kind){return `<form class="auth-form" data-auth-form="${kind}"><input class="sr-only" name="username" autocomplete="username" value="${esc(this.storeId||'one-shop-owner')}" readonly tabindex="-1">${kind==='password'?this.field('currentPassword','current-password'):''}${this.field('password',kind==='login'?'current-password':'new-password')}${kind!=='login'?this.field('confirm'):''}<p id="auth-hint" class="auth-hint">${esc(this.t(kind==='login'?'sessionNote':'passwordHint'))}</p><p id="auth-feedback" data-auth-feedback class="auth-feedback" role="alert" tabindex="-1">${this.error?esc(this.t(this.error)):''}</p><button class="button primary auth-submit" ${this.pending?'disabled':''}>${esc(this.t(this.pending?'working':kind==='login'?'login':kind==='password'?'changePassword':'savePassword'))}${icon('arrow')}</button></form>`;},
  render(){if(this.ready)return;window.scrollTo?.(0,0);document.documentElement.lang=getLang();document.title=this.t('login')+' · one shop ai';const kind=this.mode,form=['login','setup','create'].includes(kind);root.innerHTML=`<main class="owner-entry auth-entry"><header class="entry-header"><a class="platform-brand" href="../?lang=${getLang()}">${brandLogo()}</a><label class="language-select">${icon('globe')}<select id="language" aria-label="Language">${languageOptions(getLang())}</select></label></header><section class="entry-panel auth-panel"><span class="entry-badge">one shop ai · owner</span>${brandMark('greeting',true)}<h1>${esc(this.t(form?kind:'login'))}</h1>${this.name?`<p class="auth-shop">${esc(this.name)}</p>`:''}<p class="entry-intro">${esc(this.t(kind==='setup'?'setupNote':kind==='create'?'createNote':'loginNote'))}</p>${this.pending?`<p role="status">${esc(this.t('working'))}</p>`:form?this.passwordForm(kind):`<form class="auth-form" data-auth-form="lookup"><label for="auth-shop-link">${esc(this.t('shopLink'))}</label><input id="auth-shop-link" name="shop" type="text" required autocomplete="off" maxlength="1000"><p data-auth-feedback class="auth-feedback" role="alert" tabindex="-1">${this.error?esc(this.t(this.error)):''}</p><button class="button primary auth-submit">${esc(this.t('loginShop'))}${icon('arrow')}</button></form><button class="button auth-secondary" data-auth="create">${esc(this.t('newShop'))}</button>`}${!this.pending&&form?`<button class="auth-text-button" data-auth="choose">${esc(this.t('switchShop'))}</button>`:''}<a class="auth-text-button" href="recovery.html?lang=${getLang()}&v=5.12.0">${esc(recoveryCopy(getLang()).forgot)} <small>· Demo</small></a><details class="auth-help"><summary>${esc(this.t('security'))}</summary><p>${esc(recoveryCopy(getLang()).settingsNote)}</p><p>${esc(this.t('sessionNote'))}</p></details></section><footer class="entry-footer"><a href="../?lang=${getLang()}#live-demo">${esc(this.t('book'))}${icon('arrow')}</a><span>원샵 · one shop ai</span></footer></main>`;},
  settings(){return `<section class="auth-settings"><header>${brandMark('thinking',true)}<h1>${esc(this.t('security'))}</h1></header><article class="auth-settings-card"><h2>${esc(this.t('managerLink'))}</h2><p>${esc(this.t('sessionNote'))}</p><label class="sr-only" for="manager-link">${esc(this.t('managerLink'))}</label><input id="manager-link" value="${esc(this.managerLink())}" readonly><button class="button" data-auth="copy">${icon('link')}${esc(this.t('copy'))}</button></article><article class="auth-settings-card recovery-settings-card"><h2>${esc(recoveryCopy(getLang()).settingsTitle)}</h2><p>${esc(recoveryCopy(getLang()).settingsNote)}</p><a class="button" href="recovery.html?lang=${getLang()}&v=5.12.0">${esc(recoveryCopy(getLang()).tryDemo)}${icon('arrow')}</a></article><article class="auth-settings-card"><h2>${esc(this.t('changePassword'))}</h2><p>${esc(this.t('changeNote'))}</p>${this.passwordForm('password')}</article><article class="auth-settings-card"><h2>${esc(this.t('logout'))}</h2><p>${esc(this.t('logoutNote'))}</p><button class="button" data-action="demo-logout">${esc(this.t('logout'))}</button></article></section>`;}
 };
 root.addEventListener('click',async e=>{const button=e.target.closest('[data-auth]');if(!button)return;e.stopPropagation();if(auth.pending)return;const action=button.dataset.auth;if(action==='show'){const input=root.querySelector('#'+button.dataset.for);const visible=input.type==='password';input.type=visible?'text':'password';button.textContent=auth.t(visible?'hide':'show');button.setAttribute('aria-pressed',String(visible));return;}if(action==='copy'){try{await navigator.clipboard.writeText(auth.managerLink());button.textContent=auth.t('copied');}catch{root.querySelector('#manager-link').select();}return;}auth.generation++;auth.error='';auth.name='';auth.mode=action==='create'?'create':'choose';auth.storeId=null;auth.legacy=null;auth.render();});
 root.addEventListener('submit',async e=>{const form=e.target.closest('[data-auth-form]');if(!form)return;e.preventDefault();e.stopPropagation();if(auth.pending)return;const values=Object.fromEntries(new FormData(form)),kind=form.dataset.authForm;
  if(kind==='lookup'){const id=parseShopLink(values.shop);if(!id){auth.feedback('ownerAccess');return;}auth.storeId=id;auth.error='';await auth.boot();return;}
  if(kind!=='login'&&values.password!==values.confirm){auth.feedback('passwordMismatch');return;}if([...values.password||''].length<12||[...values.password||''].length>128){auth.feedback('passwordLength');return;}
  const generation=++auth.generation,baseline=auth.storeId?localStorage.getItem('modu-owner-session:'+auth.storeId):null;auth.pending=true;form.querySelector('button[type="submit"],.auth-submit').disabled=true;auth.feedback('working');let suspended=false;
  try{let credential;if(kind==='create'){const s=createOwnerSample(getLang());s.manager.messages=[];credential=await request('create','POST',{store:s.store,menu:s.items,workspace:{manager:s.manager,inventory:s.inventory,staffTasks:s.staffTasks},password:values.password,seedDemo:true});}
   else {if(kind==='password'){onSuspend();suspended=true;}credential=await request(auth.storeId+'/owner-auth/'+kind,'POST',{password:values.password,...(kind==='password'?{currentPassword:values.currentPassword}:{})},kind==='setup'?auth.legacy?.token:kind==='password'?auth.credential?.token:undefined);}
   if(generation!==auth.generation||(kind!=='create'&&localStorage.getItem('modu-owner-session:'+credential.storeId)!==baseline)){if(generation===auth.generation)auth.invalidate();await request(credential.storeId+'/owner-auth/logout','POST',{},credential.token).catch(()=>{});return;}form.reset();auth.pending=false;await auth.enter(credential);if(kind==='password')auth.feedback('saved');
  }catch(e){if(generation!==auth.generation)return;auth.pending=false;if(suspended&&auth.credential)await onReady(auth.credential);auth.feedback(e.message);form.querySelector('.auth-submit')?.removeAttribute('disabled');}
 });
 window.addEventListener('storage',e=>{if(e.key==='modu-owner-session:'+auth.storeId&&ownerCredential(localStorage,auth.storeId)?.token!==auth.credential?.token){auth.invalidate();}});
 window.addEventListener('pageshow',e=>{if(e.persisted&&auth.ready){auth.ready=false;onSuspend();auth.boot();}});
 return auth;
}
